package com.example.case1.analytics.config; import org.apache.kafka.common.TopicPartition; import org.springframework.context.annotation.*; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.kafka.listener.*; import org.springframework.util.backoff.ExponentialBackOff;
@Configuration public class KafkaRetryConfig { @Bean DefaultErrorHandler errorHandler(KafkaTemplate<String,String> template){DeadLetterPublishingRecoverer recoverer=new DeadLetterPublishingRecoverer(template,(r,e)->new TopicPartition(r.topic()+".DLT",r.partition())); ExponentialBackOff backoff=new ExponentialBackOff(1000,2.0); backoff.setMaxInterval(10000); backoff.setMaxElapsedTime(30000); return new DefaultErrorHandler(recoverer,backoff);} }
